node <<'JS'
const { chromium } = require('/tmp/node_modules/playwright');
const path = require('path');
const fs = require('fs');
(async () => {
  // Verify live source matches intent
  const html = fs.readFileSync('web/index.html','utf8');
  const js = fs.readFileSync('web/viewer.js','utf8');
  const mobileHelp = html.match(/mobile-start-help[\s\S]*?<\/div>/)[0];
  const hasGoodHelp = mobileHelp.includes('Optionally pick <b>Compare</b>') && mobileHelp.includes('above') && !/Uploaded files/i.test(mobileHelp);
  const loadStep = js.includes('Optional: with a <b>preloaded</b> trajectory, tap <b>Compare</b>') && !js.includes('Uploaded files show scores only. Press <b>Load</b>');
  const resultsStep = js.includes('Skip Compare if scores for this run are enough') && !js.includes('Uploaded files show scores only - skip Compare');
  console.log({ hasGoodHelp, loadStep, resultsStep });

  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  const file = 'file://' + path.resolve('web/usability/mobile-start-no-upload-copy.html');
  await page.goto(file, { waitUntil: 'networkidle' });
  const check = await page.textContent('#check');
  console.log({ check, scrollWidth: await page.evaluate(() => document.documentElement.scrollWidth) });
  await page.screenshot({ path: 'web/usability/mobile-start-no-upload-copy.png', fullPage: true });
  await browser.close();
  if (!hasGoodHelp || !loadStep || !resultsStep || !String(check).includes('ok=true')) process.exit(1);
})().catch(e => { console.error(e); process.exit(1); });
